const verifyHashes=(record:Record<string,string>,read:(path:string)=>Buffer=readFileSync)=>{for(const [p,expected] of Object.entries(record)){expect(expected).toMatch(/^[a-f0-9]{64}$/);const path=sourcePath(p);if(path==='src/components/calculator-interactive.tsx')expect(verifyCapturedCurrentCaller({path,sha256:expected},read)).toBe(path);else expect(createHash('sha256').update(read(path)).digest('hex')).toBe(expected);}};
